/* ---------- Data loading ---------- */
/* How long a downloaded data file may be reused before we ask the network again
 * (shared/data-cache.js).
 *
 * The day file gets an HOUR, not a day, and the reason is this page's whole
 * premise: it answers "what can I get into right now", and the SOLD OUT stamps
 * it draws are refreshed hourly by the `refresh-tickets` task. A day-long reuse
 * would have been a cache that outlived its own data — a visitor returning after
 * lunch would see the morning's availability. An hour matches the refresh that
 * feeds it, so the page is never showing something staler than the pipeline can
 * make it.
 *
 * That still buys the reuse worth having. The url is keyed by date, so this only
 * ever concerns revisits within one day, and the common ones — a reload, a
 * reopened tab, a return an hour either side of a show — skip the download
 * entirely. The planner's catalogue is the file that earns a long TTL, and it
 * earns it by carrying no availability at all.
 *
 * venues.json holds for a day: it carries no ticket status, and its lookup lists
 * are append-only, so a copy fetched today decodes anything the day file can say.
 */
const DAY_TTL_MS = 60 * 60 * 1000;
const LOOKUPS_TTL_MS = DAY_MS;

/* Load today's shows: the per-day file (only this fringe day's performances,
 * kept small) joined with the venue lookup (names + coordinates), reshaped for
 * the map and list. Only the current day is fetched, so the payload stays light.
 *
 * "Today" is the fringe day, 06:00 → 06:00 (shared/fringe-day.js), so the file
 * also carries tomorrow's small hours — the late shows someone at 23:50 is
 * actually looking for. Their `start` comes through extended ("24:30" for
 * 00:30), which is what keeps them sorting and comparing after 23:00 rather
 * than before 06:00. */
async function loadShows() {
  try {
    // Both are validated on the way out of the cache: a stored copy from an older
    // generation parses fine and then reads as an empty festival, with nothing
    // logged anywhere (#309). venues.json in particular is the same Cache Storage
    // entry the planner uses — one bad copy would take out both pages.
    const [lookups, day] = await Promise.all([
      cachedFetchJson("data/venues.json", LOOKUPS_TTL_MS, noteCache,
        (d) => Boolean(d) && typeof d.venues === "object" && d.venues !== null),
      cachedFetchJson(`data/days/${NOW.fringeDate}.json`, DAY_TTL_MS, noteCache,
        (d) => Array.isArray(d)),
    ]);
    // The shared lookup file carries the venue map plus the global rooms/genres
    // lists that the day records index into. Fetched once.
    state.venues = lookups.venues;
    state.rooms = lookups.rooms || [];
    state.genres = lookups.genres || [];
    state.subgenres = lookups.subgenres || [];
    state.ticketStatuses = lookups.ticketStatuses || [];
    // Drop shows whose venue we couldn't geocode — they can't be placed on the map.
    state.shows = day
      .map((entry, i) => adaptShow(entry, state, i))
      .filter((s) => s.lat != null && s.lng != null);
  } catch (err) {
    console.error("Could not load show data:", err);
    state.shows = [];
  }
}

/* Where the shared data cache (shared/data-cache.js) reports a cache write it
 * couldn't make or a stale copy it fell back on. Never surfaced in the UI: in
 * both cases the caller still got its data. */
function noteCache(err, url) {
  console.info("Data cache —", url, err);
}

/* Join a minimal per-day record with its venue and expand to the model the map
 * and list expect ({ id, title, genre, venue, lat, lng, time, duration, price }).
 * The day record references genre, room, subgenres and ticket status by index
 * into the global `state.genres`/`state.rooms`/`state.subgenres`/
 * `state.ticketStatuses` lookup lists (room index -1, or an unknown room,
 * resolves to no room), and stores free/soldOut as 1/0. A show can perform more
 * than once a day, so the internal id is made unique per performance. */
function adaptShow(entry, { venues, rooms, genres, subgenres, ticketStatuses }, index) {
  const v = venues[entry.venue] || {};
  const venueName = v.name || (entry.venue ? `Venue ${entry.venue}` : "Venue TBC");
  const room = rooms[entry.room];
  const ticketStatus = (ticketStatuses || [])[entry.ts] || null;
  const price = typeof entry.pm === "number" ? entry.pm : entry.free ? 0 : null;
  return {
    id: `${entry.id}__${entry.start}__${index}`,
    showId: entry.id,
    slug: entry.slug,
    title: entry.title,
    genre: genres[entry.genre],
    subgenres: (entry.subs || []).map((i) => (subgenres || [])[i]).filter(Boolean),
    venue: room ? `${venueName} — ${room}` : venueName,
    lat: v.lat ?? null,
    lng: v.lng ?? null,
    time: entry.start,
    duration: entry.duration || 60,
    free: !!entry.free,
    // `pm` is THIS performance's cheapest band in pounds, absent when the price
    // cache doesn't know it — NOT the same as free (see shared/price.js).
    // priceMin is what the filter reads; `price` is the label a card renders.
    priceMin: price,
    price: priceLabel({ priceMin: price, free: !!entry.free }),
    soldOut: !!entry.soldOut,
    ticketStatus,
    // Can you actually get a ticket online? ticketStatus is the reliable signal
    // (the soldOut flag isn't — see scraper/SCRAPING.md). Unknown ⇒ assume yes.
    available: !NO_TICKETS_STATUSES.has(ticketStatus),
  };
}

/* Ticket statuses that mean "no ticket available online" → SOLD OUT stamp.
 * Anything else (incl. unknown) is treated as available. */
const NO_TICKETS_STATUSES = new Set(["SOLD_OUT", "NO_ALLOCATION_CONTACT_VENUE"]);

/* ---------- Map ---------- */

