.genre-cluster { background: none; }
.gcluster { display: flex; align-items: center; justify-content: center; border-radius: 50%; background: var(--gold); color: #fff; font-weight: 700; font-size: 0.78rem; border: 2px solid #fff; box-shadow: 0 1px 4px rgba(16, 24, 40, 0.35); }
/* Fade the count bubbles while a show is focused, to match the dimmed pins. */
.gcluster--dim { opacity: 0.3; }
/* Leaflet attribution links — styled in site purple */
.leaflet-control-attribution { font-size: 0.65rem; }
.leaflet-control-attribution a { color: var(--blue); text-decoration: underline; }
.leaflet-control-attribution a:hover { color: var(--blue-dark); }

/* --- Reachable list: compact rows, capped --- */
.shows-section { padding: 8px 0 0; }
/* The count heading now sits above the filters + map, framing the whole area. */
.shows-title { font-size: 1.3rem; margin: 18px 0 8px; }
.shows-grid { display: flex; flex-direction: column; gap: 8px; grid-template-columns: none; }
.show-item {
  position: relative;
  display: flex; align-items: center; gap: 12px; padding: 12px 14px;
  border: 1px solid var(--line); border-radius: 12px; background: var(--paper);
  cursor: pointer; transition: border-color 0.12s ease;
}
.show-item:hover { border-color: #cfc9bb; transform: none; }
.show-item--tight { opacity: 0.6; }
.show-item--soldout { opacity: 0.6; }
.show-item--leg { border-color: var(--ok); border-width: 2px; }
.show-item--selected { border-color: var(--red); border-width: 2px; box-shadow: none; }

/* Ink-stamp overlay on cards that are sold out / no longer reachable — a bold
 * boxed word, roughened at the edges (SVG #stamp-ink filter) and eaten away in
 * patches (a turbulence mask) so it reads like a real rubber stamp. The card
 * stays clickable — the stamp ignores pointer events. */
.show-stamp {
  position: absolute; top: 50%; left: 50%;
  transform: translate(-50%, -50%) rotate(-7deg);
  z-index: 3; pointer-events: none;
  /* Heavy slab display face — the chunky letterform is what reads as a stamp
   * (loaded via Google Fonts in index.html). Alfa Slab One is already bold. */
  font-family: "Alfa Slab One", Rockwell, "Roboto Slab", var(--serif), serif;
  font-weight: 400; font-size: 1.1rem; line-height: 1;
  letter-spacing: 0.01em; text-transform: uppercase; white-space: nowrap;
  padding: 6px 15px 3px;
  border: 3px solid currentColor; border-radius: 4px;
  background: transparent;
  opacity: 0.85;
  /* Straight-ish edges (small displacement) — the worn look comes from the mask,
   * not from warping the box. */
  filter: url(#stamp-ink);
